// Developer mode's words (Astra, 2026-10-19: "another installation option that's for developers ... instead of the
// Unity unicorn and the unicorn stable, you would have the agent and the agent control hub").
// Writes apps/developer-words-20261019.js, which every page loads in its <head>: the word lists of
// developer-words-20261019.json, every pet and pet program name from pet-programs.json and pets.json with its
// developer name, then the page code (scripts/developer-words-page-20261019.js). The installer reads the same JSON
// for its own window. apps/words-mode-20261019.js is not generated: the installer writes the mode into it.
// Run by `npm run build`; `node scripts/developer-words-20261019.mjs` writes the file alone.
// Claude Opus 5.5 (claude-opus-5-5), 2026-10-19.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { assertPublic } from './public-safety-20261014.mjs';

export const SOURCE = 'developer-words-20261019.json';
export const OUTPUT = 'apps/developer-words-20261019.js';
export const MODE_FILE = 'apps/words-mode-20261019.js';
export const PAGE_CODE = 'scripts/developer-words-page-20261019.js';

// The same slug as the pet program spawner's (scripts/pet-program-pages-20261018.mjs), so panel labels match.
export const slug = (s) => String(s).toLowerCase().replace(/['’]/g, '').replace(/&/g, ' ').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
// Names are written with either apostrophe ("Mommy's" and "Mommy’s"), so both count.
const spellings = (name) => [...new Set([name, name.replace(/’/g, "'"), name.replace(/'/g, '’')])];

/** Every pet program's developer names, by repo: { agent, hub, pet, home }. A program with no developer name yet keeps
 *  its farm names in developer mode (listed in `missing`), so a page never shows a half-made name. */
export function developerNames(words, programs, registry = {}) {
  const pets = new Map([...(registry.pets || []), ...(registry.pipeline || [])].map((p) => [p.repo, p.pet]));
  const names = {}, missing = [];
  for (const p of programs) {
    const dev = words.names?.[p.repo];
    if (!dev?.agent) { missing.push(p.repo); continue; }
    // keep_home: the pet program is named after the project it runs (Data Dealer), so that name stays.
    const home = p.assigned ? p.program : null;
    names[p.repo] = { agent: dev.agent, hub: dev.keep_home && home ? home : dev.hub || `${dev.agent} Control Hub`, pet: p.icon || pets.get(p.repo) || null,
      also: pets.get(p.repo) && pets.get(p.repo) !== p.icon ? pets.get(p.repo) : null, home: dev.keep_home ? null : home };
  }
  return { names, missing };
}

/** What the page code needs: the exact pairs (names first), the other words, the panel endings and the slugs. */
export function pageWords(words, programs, registry) {
  const { names, missing } = developerNames(words, programs, registry);
  const exact = [], slugs = [];
  for (const n of Object.values(names)) {
    for (const pet of [n.pet, n.also].filter(Boolean)) {
      for (const s of spellings(pet)) exact.push([s, n.agent]);
      slugs.push([slug(pet), slug(n.agent)]);
    }
    if (n.home) {
      for (const s of spellings(n.home)) exact.push([s, n.hub]);
      slugs.push([slug(n.home), slug(n.hub)]);
    }
  }
  return {
    exact: [...exact, ...words.exact.flatMap(([from, to]) => spellings(from).map((s) => [s, to]))], words: words.words, panels: words.panels,
    slugs: [...new Map(slugs.map((p) => [p[0], p])).values()],
    names: Object.fromEntries(Object.entries(names).map(([repo, n]) => [repo, { agent: n.agent, hub: n.hub }])),
    missing,
  };
}

export function buildDeveloperWordsScript(data, pageCode) {
  const { missing, ...shipped } = data;
  return `// Generated by scripts/developer-words-20261019.mjs from ${SOURCE}, pet-programs.json and pets.json (npm run build).
// Do not edit by hand: change ${SOURCE} or ${PAGE_CODE}, then build.
window.PetOSWordsData = ${JSON.stringify(shipped)};
${pageCode}`;
}

export function readDeveloperWordsSources(root = '.') {
  const j = (p) => JSON.parse(readFileSync(`${root}/${p}`, 'utf8').replace(/^﻿/, ''));
  return { words: j(SOURCE), programs: j('pet-programs.json').programs, registry: j('pets.json'),
    pageCode: readFileSync(`${root}/${PAGE_CODE}`, 'utf8') };
}

export function developerWordsFile(src) {
  const data = pageWords(src.words, src.programs, src.registry);
  return { data, script: assertPublic(buildDeveloperWordsScript(data, src.pageCode), OUTPUT) };
}

export function writeDeveloperWords(root = '.') {
  const { data, script } = developerWordsFile(readDeveloperWordsSources(root));
  writeFileSync(`${root}/${OUTPUT}`, script);
  if (!existsSync(`${root}/${MODE_FILE}`)) throw new Error(`${MODE_FILE} is missing: the installer writes Developer mode into it.`);
  return data;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  process.chdir(fileURLToPath(new URL('..', import.meta.url)));
  const data = writeDeveloperWords('.');
  console.log(`Wrote ${OUTPUT}: ${Object.keys(data.names).length} pet programs in developer words${data.missing.length ? `; no developer name yet: ${data.missing.join(', ')}` : ''}.`);
}
